import type { GatewaySessionRow } from "../../api/types.ts";
import type { ApplicationContext } from "../../app/context.ts";
import { isArchiveHeld, subscribeHeldArchives } from "../../components/session-archive-hold.ts";
import { resolveSessionDisplayName } from "../../lib/session-display.ts";
import { collectKnownSessionGroups } from "../../lib/sessions/grouping.ts";
import { resolveSessionKey, scopedAgentParamsForSession } from "../../lib/sessions/navigation.ts";
import { areUiSessionKeysEquivalent } from "../../lib/sessions/session-key.ts";
import { resolveChatPaneParentSession } from "./chat-pane-header-identity.ts";
import type { ChatPageHost } from "./chat-state-host.ts";
import { resolveChatAgentId } from "./chat-state-route.ts";

export function chatSessionPresentationTitle(
  state: Pick<ChatPageHost, "sessions" | "sessionKey" | "hello"> | undefined,
  row?: GatewaySessionRow,
  sessionKey = "",
  pending = false,
  createdTitle?: string,
): string {
  const key = state
    ? resolveSessionKey(state.sessionKey, state.hello) || state.sessionKey
    : sessionKey;
  const presentation = state?.sessions.presentation.result?.sessions.find((candidate) =>
    areUiSessionKeysEquivalent(candidate.key, key),
  );
  // The roster owns accepted titles; pane metadata fills absent cross-agent rows.
  const source = presentation ?? row;
  if (!source && createdTitle) {
    return createdTitle;
  }
  if (!source && pending) {
    return "";
  }
  return presentation
    ? resolveSessionDisplayName(key, presentation)
    : resolveSessionDisplayName(row?.key ?? key, row);
}

/** The presentation key changes with the roster and when a held archive starts sending. */
export function watchPresentation(
  sessions: Pick<ApplicationContext["sessions"], "subscribe">,
  notify: () => void,
): () => void {
  const stops = [sessions.subscribe(notify), subscribeHeldArchives(notify)];
  return () => stops.forEach((stop) => stop());
}

/** Capture rendered roster facts without retaining a mutable row as the previous value. */
export function chatSessionPresentationKey(
  state: ChatPageHost,
  publication: ApplicationContext["sessions"]["state"],
  selected: GatewaySessionRow | undefined,
  globalApprovals: ApplicationContext["overlays"]["snapshot"]["approvalQueue"] | undefined,
): string {
  const result = state.sessionsResult;
  const rows = result?.sessions ?? [];
  const approvalSources = new Set(
    [...(state.chatSessionApprovalQueue ?? []), ...(globalApprovals ?? [])]
      .map((approval) => approval.sourceSessionKey)
      .filter((key): key is string => typeof key === "string"),
  );
  return JSON.stringify([
    state.sessionKey,
    resolveChatAgentId(state),
    state.connectionEpoch,
    state.sessionsResultAgentId,
    state.sessionsLoading,
    state.sessionsError,
    selected,
    chatSessionPresentationTitle(state),
    resolveChatPaneParentSession(selected, rows),
    result?.defaults,
    result?.owners,
    publication.modelOverrides[state.sessionKey],
    Object.hasOwn(publication.modelOverrides, state.sessionKey),
    state.sessions.think(
      state.sessionKey,
      scopedAgentParamsForSession(state, state.sessionKey).agentId,
    ),
    state.sessions.archiveVisibility(selected?.key ?? state.sessionKey),
    isArchiveHeld(selected?.key ?? state.sessionKey),
    collectKnownSessionGroups(publication.groups, publication.result?.sessions ?? []),
    publication.groupSettings,
    [...approvalSources].map((key) => rows.find((row) => areUiSessionKeysEquivalent(row.key, key))),
    // Empty chat renders recent sessions from the whole roster.
    state.chatMessages.length === 0 ? rows : undefined,
  ]);
}
