import type { ChatAppContextAttachment } from "../../../../packages/gateway-protocol/src/chat-app-context.js";
import type { ChatWorkContext } from "../../../../packages/gateway-protocol/src/chat-work-context.js";
import type {
  ChatSendIntent,
  QueueMode,
} from "../../../../packages/gateway-protocol/src/schema/logs-chat.js";
import { GATEWAY_STARTUP_ADMISSION_WAIT_MS } from "../../../../packages/gateway-protocol/src/startup-unavailable.js";
import { t } from "../../i18n/index.ts";
import type { ChatAttachment, HumanMention } from "../../lib/chat/chat-types.ts";
import {
  isUiGlobalSessionKey,
  normalizeAgentId,
  resolveUiSelectedSessionAgentId,
  resolveUiConversationIdentity,
} from "../../lib/sessions/session-key.ts";
import { assertUploadsEnabled } from "../../lib/uploads.ts";
import { buildChatApiAttachments } from "./attachment-api.ts";
import { isInitialChatHistoryUnavailable } from "./chat-history-state.ts";
import { chatOutboxOwner } from "./chat-outbox-owner.ts";
import { chatProviderReviewRow } from "./chat-provider-review.ts";
import { normalizeChatSendAck, type ChatSendAck } from "./chat-send-ack.ts";
import type { ChatState } from "./chat-state-contract.ts";

export async function requestChatSend(
  state: ChatState,
  params: {
    message: string;
    appContext?: ChatAppContextAttachment[];
    workContext?: ChatWorkContext;
    mentions?: readonly HumanMention[];
    attachments?: ChatAttachment[];
    runId: string;
    sessionKey?: string;
    agentId?: string;
    queueMode?: QueueMode;
    intent?: ChatSendIntent;
    sessionId?: string;
    replyToId?: string;
    expectedLeafEntryId?: string | null;
  },
): Promise<ChatSendAck> {
  if (params.attachments?.length) {
    assertUploadsEnabled(state.uploadConfig);
  }
  const sessionKey = params.sessionKey ?? state.sessionKey;
  if (sessionKey === state.sessionKey && state.isRouteSessionPending?.()) {
    throw new Error(t("chat.thread.loading"));
  }
  const selectedAgentId = params.agentId
    ? normalizeAgentId(params.agentId)
    : resolveUiSelectedSessionAgentId(state);
  const currentSessionId = state.currentSessionId;
  const canReuseCurrentSessionId =
    sessionKey === state.sessionKey &&
    (!isUiGlobalSessionKey(sessionKey) ||
      (selectedAgentId !== undefined &&
        selectedAgentId === resolveUiSelectedSessionAgentId(state)));
  const routingSessionId =
    canReuseCurrentSessionId && typeof currentSessionId === "string" && currentSessionId.trim()
      ? currentSessionId.trim()
      : undefined;
  if (chatProviderReviewRow(state, sessionKey, selectedAgentId)?.providerReview) {
    throw new Error(t("chat.providerReview.pausedBody"));
  }
  const sessionId = params.sessionId ?? (params.intent ? undefined : routingSessionId);
  const controlUiReconnectResume = Boolean(
    !params.intent && sessionId && state.reconnectResumeSessionId === sessionId,
  );
  const attachments = buildChatApiAttachments(params.attachments);
  const hasAudio = attachments?.some((attachment) =>
    attachment.mimeType.toLowerCase().startsWith("audio/"),
  );
  const request = chatOutboxOwner(state).admissions.beginRequest(
    state,
    resolveUiConversationIdentity(state, sessionKey, selectedAgentId),
    params.runId,
  );
  let payload: unknown;
  try {
    payload = await state.client!.request(
      "chat.send",
      {
        sessionKey,
        ...(isUiGlobalSessionKey(sessionKey) && selectedAgentId
          ? { agentId: selectedAgentId }
          : {}),
        ...(sessionId ? { sessionId } : {}),
        ...(controlUiReconnectResume ? { __controlUiReconnectResume: true } : {}),
        message: params.message,
        ...(params.workContext ? { workContext: params.workContext } : {}),
        ...(params.appContext ? { appContext: params.appContext } : {}),
        ...(params.mentions?.length ? { mentions: params.mentions } : {}),
        ...(params.intent ? { intent: params.intent } : {}),
        deliver: false,
        ...(params.replyToId ? { replyToId: params.replyToId } : {}),
        ...(params.queueMode ? { queueMode: params.queueMode } : {}),
        ...(params.expectedLeafEntryId !== undefined
          ? { expectedLeafEntryId: params.expectedLeafEntryId }
          : {}),
        idempotencyKey: params.runId,
        attachments,
      },
      // Audio transcription precedes admission; cancellation and connection lifetime
      // still own that wait. Text retains the bounded startup admission deadline.
      {
        timeoutMs: hasAudio ? null : GATEWAY_STARTUP_ADMISSION_WAIT_MS,
        signal: request.signal,
        retainSentResultOnAbort: true,
      },
    );
  } finally {
    request.release();
  }
  if (controlUiReconnectResume) {
    state.reconnectResumeSessionId = null;
  }
  return normalizeChatSendAck(payload, params.runId);
}

export function resolveDisplayedLeafEntryId(state: ChatState): string | null | undefined {
  if (state.chatLoading || isInitialChatHistoryUnavailable(state)) {
    return undefined;
  }
  if (state.chatDisplayedLeafEntryId === null) {
    return null;
  }
  const leafEntryId = state.chatDisplayedLeafEntryId?.trim();
  return leafEntryId || undefined;
}
